#ifndef J3D_PLATFORM_J3DGUI_TEMPLATES_H
#define J3D_PLATFORM_J3DGUI_TEMPLATES_H
/*
 * The dialog templates of Jones3D/Indy3D.rc as C tables (PORT-PLAN.md P6.2), generated by tools/rc2table.py into
 * gui_templates.c. Coordinates are dialog units.
 */
#include <Windows.h>

typedef struct J3DGuiTemplateItem
{
    const char* pClass;     // "Button", "Static", "ComboBox", "ListBox", "Edit", "ScrollBar", "msctls_trackbar32", "SysListView32"
    const char* pText;
    int id;
    DWORD style;
    DWORD exStyle;
    short x, y, cx, cy;
    int iconId;             // an ICON statement's resource ID, else 0
} J3DGuiTemplateItem;

typedef struct J3DGuiTemplate
{
    int id;
    DWORD style;
    short x, y, cx, cy;
    const char* pCaption;
    const char* pFontName;
    int fontSize;           // points
    const J3DGuiTemplateItem* pItems;
    int numItems;
} J3DGuiTemplate;

// DLGINIT: a message sent to a control after the dialog's controls exist (0x403 is CB_ADDSTRING), with its string.
typedef struct J3DGuiTemplateInit
{
    int dialogId;
    int controlId;
    UINT msg;
    const char* pData;
} J3DGuiTemplateInit;

typedef struct J3DGuiIconResource
{
    int id;
    const char* pFileName;
} J3DGuiIconResource;

extern const J3DGuiTemplate J3DGui_aTemplates[];
extern const int J3DGui_numTemplates;
extern const J3DGuiTemplateInit J3DGui_aTemplateInits[];
extern const int J3DGui_numTemplateInits;
extern const J3DGuiIconResource J3DGui_aIconResources[];
extern const int J3DGui_numIconResources;

#endif
